[McpServerResourceType]
public class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new { Logging = true, Metrics = false }
        };
        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource(UriTemplate = "config://app/health",
        Name = "Health Status",
        Description = "Returns the server health status.")]
    public static string GetHealthStatus()
    {
        return System.Text.Json.JsonSerializer.Serialize(new
        {
            Status = "Healthy",
            Uptime = Environment.TickCount64 / 1000,
            Timestamp = DateTime.UtcNow
        }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

