using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings")]
    [Description("Returns the application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = System.Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new { Logging = true, Metrics = false }
        };
        return JsonSerializer.Serialize(config, JsonOptions);
    }

    [McpServerResource(UriTemplate = "config://app/health", Name = "Health Status")]
    [Description("Returns the server health status.")]
    public static string GetHealthStatus()
    {
        return JsonSerializer.Serialize(new
        {
            Status = "Healthy",
            Uptime = System.Environment.TickCount64 / 1000,
            Timestamp = DateTime.UtcNow
        }, JsonOptions);
    }
}

